<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {useForecastStore} from '../stores/forecast';import ComparisonChart from '../components/chart/ComparisonChart.vue';import type {Forecast} from '../types';const store=useForecastStore(),selected=ref<Forecast|null>(null),filter=ref('ALL'),summary=ref({total:0,completed:0,monitoring:0,directionalCorrect:0}),rows=computed(()=>store.history.filter(f=>filter.value==='ALL'||f.status===filter.value)),fmt=(n:number)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});async function open(f:Forecast){selected.value=await store.detail(f.id)}async function refresh(){await Promise.all([store.loadHistory(),fetch('/api/prediction-history/summary').then(r=>r.json()).then(x=>summary.value=x)])}onMounted(refresh);</script>
<template><section class="view"><div class="page-heading"><div><div class="eyebrow">FORWARD PERFORMANCE</div><h1>Lịch sử dự đoán</h1><p>Dự báo gốc không bị thay đổi; nến thực và đánh giá được lưu riêng trong SQLite.</p></div><button class="icon-button" @click="refresh">⟳</button></div><div class="metrics-grid"><div v-for="item in [['Tổng dự báo',summary.total],['Đã hoàn tất',summary.completed],['Đang theo dõi',summary.monitoring],['Đúng hướng',summary.completed?`${Math.round(summary.directionalCorrect/summary.completed*100)}%`:'—']]" :key="item[0]" class="metric"><small>{{item[0]}}</small><b>{{item[1]}}</b></div></div><div class="panel history-panel"><div class="panel-title"><span>TẤT CẢ DỰ BÁO</span><select v-model="filter"><option value="ALL">Tất cả trạng thái</option><option>MONITORING</option><option>PARTIALLY_EVALUATED</option><option>COMPLETED</option><option>DATA_DELAYED</option></select></div><div class="table-wrap"><table><thead><tr><th>THỜI ĐIỂM</th><th>KHUNG</th><th>HƯỚNG</th><th>GIÁ DỰ BÁO</th><th>GIÁ THỰC</th><th>TIẾN ĐỘ</th><th>TRẠNG THÁI</th></tr></thead><tbody><tr v-for="f in rows" :key="f.id" class="click-row" @click="open(f)"><td>{{new Date(f.created_at).toLocaleString('vi-VN')}}</td><td>{{f.timeframe}} · {{f.horizon}}</td><td :class="f.signal.toLowerCase()">{{f.signal}}</td><td>{{f.predictedFinal?fmt(f.predictedFinal):'—'}}</td><td>{{f.actualFinal?fmt(f.actualFinal):'—'}}</td><td>{{f.progress}} / {{f.horizon}}</td><td><span class="status-pill" :class="{done:f.status==='COMPLETED'}">{{f.status}}</span></td></tr><tr v-if="!rows.length"><td colspan="7" class="empty-row">Chưa có dự báo trong bộ lọc này.</td></tr></tbody></table></div></div><div v-if="selected" class="panel detail"><div class="panel-title"><span>SO SÁNH DỰ BÁO · {{selected.id.slice(0,8)}}</span><button class="icon-button" @click="selected=null">×</button></div><h3>{{selected.timeframe}} · {{selected.signal}} · {{selected.status}} · {{selected.progress}}/{{selected.horizon}}</h3><ComparisonChart :forecast="selected"/><p v-if="selected.evaluation">Hướng: {{selected.evaluation.direction}} · Sai số giá cuối: {{fmt(selected.evaluation.priceError)}} · Điểm đường đi: {{selected.evaluation.pathScore.toFixed(1)}}/100</p></div></section></template>
